SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(t),'identity',to_jsonb(pg_identify_object('pg_type'::regclass,t.oid,0)),'owner',pg_get_userbyid(t.typowner),'formatted_type',format_type(t.oid,NULL),'element',CASE WHEN t.typelem<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,t.typelem,0)) END,'array',CASE WHEN t.typarray<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,t.typarray,0)) END,'relation',CASE WHEN t.typrelid<>0 THEN to_jsonb(pg_identify_object('pg_class'::regclass,t.typrelid,0)) END,'base',CASE WHEN t.typbasetype<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,t.typbasetype,0)) END,'default',pg_get_expr(t.typdefaultbin,0,false),'handlers',(SELECT jsonb_agg(jsonb_build_object('field',h.field,'oid',h.oid,'rendered',h.oid::regproc::text,'identity',CASE WHEN h.oid<>0 THEN to_jsonb(pg_identify_object('pg_proc'::regclass,h.oid,0)) END) ORDER BY h.field) FROM (VALUES ('typinput',t.typinput::oid),('typoutput',t.typoutput::oid),('typreceive',t.typreceive::oid),('typsend',t.typsend::oid),('typmodin',t.typmodin::oid),('typmodout',t.typmodout::oid),('typanalyze',t.typanalyze::oid),('typsubscript',t.typsubscript::oid)) h(field,oid))) ORDER BY t.oid),'[]'::jsonb) AS payload FROM pg_type t WHERE t.typnamespace='public'::regnamespace OR t.typrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture